import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Create Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-3-create-agency/sequence-flow.md","filePath":"feature/agency-workspace/3-4-3-create-agency/sequence-flow.md"}'),n={name:"feature/agency-workspace/3-4-3-create-agency/sequence-flow.md"};function i(l,e,c,s,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-create-agency" tabindex="-1">Sequence Flow — Create Agency <a class="header-anchor" href="#sequence-flow-—-create-agency" aria-label="Permalink to &quot;Sequence Flow — Create Agency&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.3). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — signed in; owns no Agency yet, or wants another one.</li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>agency_members</code>).</li></ul><hr><h2 id="flow-a-—-create-an-agency-without-a-logo" tabindex="-1">Flow A — Create an Agency (without a logo) <a class="header-anchor" href="#flow-a-—-create-an-agency-without-a-logo" aria-label="Permalink to &quot;Flow A — Create an Agency (without a logo)&quot;">​</a></h2><ol><li>User → Client: opens the Create Agency form and fills in the name, plus any optional branding values (description, category, company size, website, phone, location, brand colour, logo icon, tagline, founded year, Facebook, LinkedIn and Instagram links).</li><li>Client → System: submits the form (<code>POST /api/v1/agencies</code>).</li><li>System — create the Agency: a. Validates the name as mandatory — empty → <code>400 VALIDATION_ERROR</code>. b. Validates the brand colour at 9 characters and the tagline at 140 characters — over the limit → <code>400 VALIDATION_ERROR</code>. c. Stores a new Agency with the current user as its Owner and the status ACTIVE. d. Stores a member record for the Agency with the current user at the OWNER role.</li><li>System → Client: the profile of the new Agency, including its identifier.</li><li>Client: moves the user into the Agency just created. The Agency Dashboard (3.4.2) has no screen of its own yet, so the Agency Profile (3.4.4) is shown in the meantime.</li></ol><h2 id="flow-b-—-upload-a-logo-once-the-agency-exists" tabindex="-1">Flow B — Upload a logo once the Agency exists <a class="header-anchor" href="#flow-b-—-upload-a-logo-once-the-agency-exists" aria-label="Permalink to &quot;Flow B — Upload a logo once the Agency exists&quot;">​</a></h2><ol><li>Continuation of Flow A step 5, or the edit screen later on.</li><li>User → Client: picks the logo image file.</li><li>Client → System: submits the file for the Agency (<code>POST /api/v1/agencies/{agencyId}/logo</code>, sent as multipart form data).</li><li>System: stores the file and fills in the logo of the Agency.</li><li>System → Client: the Agency profile carrying the new logo location.</li><li>Client: refreshes the logo preview.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Create</td><td>Name empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Create</td><td>Value over its limit (brand colour over 9 characters, tagline over 140 characters)</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Logo upload</td><td>The file cannot be read</td><td>400</td><td><code>FILE_READ_ERROR</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>No divergence from <code>spec.md</code>. The logo is uploaded separately from the main form, matching the built behaviour where the logo upload is a step of its own rather than part of the Agency creation.</li></ul>',14)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
